class Solution:
    def maximumXorProduct(self, a: int, b: int, n: int) -> int:
        MOD = 10**9 + 7
        shared = 0
        diff_sum = 0
        diff_bits = []

        for i in range(n):
            a_i = (a >> i) & 1
            b_i = (b >> i) & 1
            if a_i == b_i:
                shared += (1 << i)
            else:
                diff_bits.append(1 << i)
                diff_sum += (1 << i)

        S = 0
        for val in sorted(diff_bits, reverse=True):
            if diff_sum - 2 * S >= val:
                S += val

        A = shared + S
        B = shared + diff_sum - S
        return (A * B) % MOD
```

