class Solution:
    def countPrefixSuffixPairs(self, words: List[str]) -> int:
        count = 0
        n = len(words)
        for i in range(n):
            for j in range(i + 1, n):
                str1 = words[i]
                str2 = words[j]
                l = len(str1)
                if str1 == str2[:l] and str1 == str2[-l:]:
                    count += 1
        return count
